def compute(vars):
    denominator = vars["v2"]
    if denominator == 0:
        return None

    value = vars["v1"] / denominator

    return {
        "value": value,
        "trace": {
            "approved_outstanding_options": vars["v1"],
            "total_outstanding_options": denominator,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "ratio"
            }
        }
    }
